-- M31 exact event authority, tables, grants and controlled telemetry expansion.
DO $retry_events_verify$
DECLARE item record;actual text;
BEGIN
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=31) THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=31 AND name='retry_events') THEN RAISE EXCEPTION 'Retry event migration identity drift';END IF;
 FOR item IN SELECT * FROM(VALUES ('coding_retry_event_admissions','add492a23e103081a5bb75f0967176252c803afc4f08629cf431f5d38b25884b'),('coding_retry_event_observations','aac303ed7bdc235867fd2d97b81f60aa0c7ba61ff98c099b846ddaad163b18ab'),('coding_retry_events','2f5e886babbc5e1842e6c6cd82e739e580ae2e03e91e98d5c9e5bfc47fc93b51'),('coding_retry_review_events','8d466536cc616452e12311384e30db99aa80c65f4081c2be3e34309bbbe41479'),('delivery_retry_event_links','d8e9683864bb31ac9431bac66dbb7f8f5f0e7dc80343564a72e2cd8fbeec0716')) expected(name,fingerprint) LOOP
 SELECT encode(sha256(convert_to(jsonb_build_object('table',jsonb_build_array(c.relkind,c.relpersistence,pg_get_userbyid(c.relowner),c.relrowsecurity,c.relforcerowsecurity,c.relreplident,c.reloptions),'acl',to_jsonb(c.relacl),'columns',(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.contype,k.convalidated,k.condeferrable,k.condeferred,pg_get_constraintdef(k.oid,false)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),'indexes',(SELECT jsonb_agg(jsonb_build_array(ic.relname,i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),'triggers',(SELECT jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,false)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal))::text,'UTF8')),'hex') INTO actual FROM pg_class c WHERE c.oid=('forge_agent.'||item.name)::regclass;
 IF actual IS DISTINCT FROM item.fingerprint THEN RAISE EXCEPTION 'Retry event table drift: %',item.name;END IF;
 END LOOP;
 FOR item IN SELECT * FROM(VALUES ('forge_agent._retry_event_dto(forge_agent.coding_retry_events)','792d0cfb70094354b0b7e02234eb895bf3732d38e6b2c000dac078e3b23613b8'),('forge_agent._retry_legacy_constraint(oid,text,text)','b68bc0b11667051c00ca9a2a433e8e22a79f0f4ec9d28e3f8e5681041c2f0b0f'),('forge_agent._retry_legacy_source(oid,text)','f9d81f958fe10c75ae1d58db20549c0f7cbcc2f69e880d816e79b6d239c84de5'),('forge_agent._retry_native_context(uuid)','588de23387a92a3ec538b7a56b6b5d7a5617262534523a5c0ab1f74c58ad5288'),('forge_agent._retry_native_observe(uuid,jsonb)','87e76ab6486d7ba4ae4006c125a73c9f0b29a11a0d89779f4598ce2a52b3ebe7'),('forge_agent._retry_native_patches()','93b62a743a88241b0e6f5f964ea7977b7243cfa2a52b0e48cca30cc45fadaec4'),('forge_agent._retry_replacement_fingerprint(text)','1526e1b514b55817d3ae794bf108254ef0fe93d11011ac68f8d55548b4938880'),('forge_agent._retry_scope(text,text,uuid)','871bce366600630a854dfee11d4f8c47d78ebdd7809f629b1aeeb64c04059bb3'),('forge_agent.coding_schedule_repair(uuid,uuid)','70bf8dbfc6097dff657c09ec76139c60ec3a31a54041baf21b14c85c9c78587c'),('forge_agent.delivery_enqueue_successors(uuid)','bf02fe6fa3276718a299155673e204391a4cf80d13e3f5692471ec66d6669fcc'),('forge_agent.delivery_main_receipt_valid(jsonb,jsonb,text)','61f94ff76b6f5d1c7e3f266ae7f1f43350095e37f75b8499eac93c458b3de6ed'),('forge_agent.delivery_own_cleanup(uuid,jsonb,jsonb,text)','a5ec377dbc07a37e60a5efe34f61495d2aadb1bc4f417158aa857cc4b9439260'),('forge_agent.delivery_repair_checkpoint(uuid,integer,uuid,jsonb)','8e33e1379381853972793d63b59f48c309c4f43be23fdccfd4ac38c342fc47ca'),('forge_agent.delivery_repair_claim(text)','5beea2b57acd94ac3e164de12ae79bde854f07b28d0369f5786a221084cf1d0c'),('forge_agent.delivery_request_valid(jsonb,uuid,uuid,text,text,text,uuid)','af51648bce3ef5cd7949e624d52d2d8729e99d782c4c3cb1863b9d3df5111250'),('forge_agent.delivery_retry_observe(uuid)','37736dcc8e4aeb1a9f3f92ec0815f5034978cd31db183632c070998f2de604d8'),('forge_agent.delivery_retry_projection(text,uuid)','e9b371025609f01fe613ff14ed18fc5fc8c4000322409ec0b17864cc02633166'),('forge_agent.retry_event_adopt_legacy(uuid,integer,text,text)','786c02875073b3daf1c31fa0ab5affde9814bbecf4200367e1d5bef4e3724559'),('forge_agent.retry_event_bind_review(uuid,uuid,text)','e903494e1882f55f7febe8832d41f081a59879359661ecdbacbb8e7949701077'),('forge_agent.retry_event_get(uuid)','637318df364d94b78c7bcb4a6e694236028eed716077ba9b7b575c4cbb46fdb5'),('forge_agent.retry_event_observe(text,text,uuid,text,text,text,text[],text,text[])','1c22b4b1a26f1c78fee6a226c0d0d81e1837051273b38ae859dcbf4e3583c952'),('forge_agent.retry_event_project(text,text,uuid)','dc582b6b2e7feb8031bafec0e305d01f28ef3f14863262ecdefc06477c5b7d94'),('forge_agent.retry_event_reserve(uuid,text)','d40eb47446bb92b1b8169d88e00599dfb371f87b0d2aa7174d4c8ba98077d0fd'),('forge_agent.retry_event_resolve(text,text,uuid,text,text,text,text)','0fbfbbaac068a92854d9810a2e641cc44481fcc17790ec810aa6db0e1e8099cc'),('forge_coding_reconciler_api.post_merge_checkpoint(uuid,integer,uuid,jsonb)','7dfd2b9b9987803e7ffab3c367281815319f6cc46f73f0ac9f0e735a2db23342'),('forge_coding_reconciler_api.post_merge_finish(uuid,integer,uuid,text,jsonb,text)','b8168f10ac3eb421910f613a5380a0eee40393b8ee918bfcbdc446efdb3805d4'),('forge_coding_reconciler_api.review_claim(text)','1c1a43dc5cbfdc9ee1c5f6066f9d3c978ba4a3871d8a6d9490a2a27bd635512e'),('forge_coding_reconciler_api.review_finish(uuid,uuid,jsonb)','59b07d8344a8c681d881f63d1a61624025326bf10fae78f64fb4263244c27a05')) expected(signature,fingerprint) LOOP
 SELECT encode(sha256(convert_to(jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl)::text,'UTF8')),'hex') INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(item.signature);
 IF actual IS DISTINCT FROM item.fingerprint THEN RAISE EXCEPTION 'Retry event function drift: %',item.signature;END IF;
 END LOOP;
END;$retry_events_verify$;
